/*!
 * wega-music-endless3.js - ENDLESS add-on for the Wega's Challenge music pack.
 * The game loads it by itself when an ENDLESS run needs it (it is not in index.html): it registers a lazy
 * "endless3" track with WegaMusic, decoded only while it plays. The music changes every 10 floors
 * (Endless, then Endless 1-5); the shop between floors has its own theme.
 * ENDLESS 3 (floors 31-40) - supplied by the player. Loops with a crossfade from 159.7 s (where its reverb tail starts) back to the top.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-endless3.js] load wega-music.js first"); return; }
  D.endless3 = {
    title: "ENDLESS 3 (floors 31-40)",
    credit: "supplied by the player",
    duration: 165.303,
    loopStart: 0.0,
    loopEnd: 159.7,
    xfade: 2.5,
    gain: 0.91,
    lazy: true,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("endless3") < 0) W.tracks.push("endless3");
  if (W.onPack) W.onPack("endless3");
})(typeof window !== "undefined" ? window : globalThis);
